import path from "node:path";
import { fileURLToPath } from "node:url";
import { migrate as runMigrations } from "drizzle-orm/node-postgres/migrator";
import { db } from "./client.js";
import { pool } from "./pool.js";

// server/drizzle, generated by `npm run db:generate`. The same relative path works from
// src/ (tsx) and dist/ (compiled), so no files need copying at build time.
const migrationsFolder = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../../drizzle");

export async function migrate(): Promise<void> {
  // pgvector is used by later phases (embeddings); drizzle-kit does not generate this.
  await pool.query("CREATE EXTENSION IF NOT EXISTS vector");
  await runMigrations(db, { migrationsFolder });
}
